        if (saveThreshold) this.proofThresholdTyped.set(true);
        if (saveNoteThreshold) this.noteThresholdTyped.set(true);
        if (saveRounding) this.roundingTyped.set(true);
        if (saveTerms) this.termsTyped.set(true);
